package it.frociart.app;
import android.app.Activity;import android.view.*;import android.widget.*;import java.util.*;import java.util.function.Consumer;import static it.frociart.app.FlowModel.*;
/** Read-only compact navigation. Editing/execution always returns to the real graph. */
final class FlowCycleOverview {
 static final class Navigation {String nodeId,checkId;boolean parameters;}
 final FlowCycleView model;final FlowCanvasView preview;final Ui.Button choose,toggle,open,parameters;final TextView status;final FrameLayout host;
 private final Activity owner;private final Ui.Sheet sheet;private final Consumer<Navigation> navigate;private FlowCycleView.Projection projection;private FlowCycle.Info selected;private String nodeId;private Ui.Sheet child;
 FlowCycleOverview(Activity activity,Ui.Sheet s,Document graph,Consumer<Navigation> action){owner=activity;sheet=s;navigate=action;model=new FlowCycleView(graph);selected=model.cycles.isEmpty()?null:model.cycles.get(0);nodeId=selected==null?null:selected.entry;
  choose=new Ui.Button(owner,"Scegli ciclo","undo",0);choose.setTag("cycle-choose");choose.setSingleLine(false);choose.setMaxLines(3);choose.setEllipsize(null);choose.setMinimumHeight(Ui.dp(owner,54));choose.setOnClickListener(v->chooseCycle());sheet.body.addView(choose,new LinearLayout.LayoutParams(-1,-2));Ui.gap(sheet.body,8);
  host=new FrameLayout(owner);preview=new FlowCanvasView(owner);preview.setTag("cycle-overview-canvas");preview.setReadOnly(true);preview.setDark(Ui.dark);preview.setMotionEnabled(Ui.motion);preview.setNavigationPreview(true);preview.setContentDescription("Panoramica dei cicli. Tocca un ciclo per espanderlo. Usa Scegli ciclo ed Espandi per navigare anche senza gesti.");host.addView(preview,new FrameLayout.LayoutParams(-1,-1));sheet.body.addView(host,new LinearLayout.LayoutParams(-1,Ui.dp(owner,320)));
  status=Ui.note(owner,"");status.setTag("cycle-overview-status");status.setTextIsSelectable(true);Ui.gap(sheet.body,8);sheet.body.addView(status);Ui.gap(sheet.body,8);
  sheet.action("Tutto · adatta la panoramica","align",0,()->preview.arrangeAnimated(FlowPlacement.positions(preview.getDocument())));
  sheet.action("Espandi ciclo","expand",1,()->{if(selected!=null){model.set(selected.check,!model.isFolded(selected.check));refresh(true);}});toggle=(Ui.Button)sheet.body.getChildAt(sheet.body.getChildCount()-2);toggle.setTag("cycle-toggle");
  // Keep the primary navigation action above the drawing, even on a short screen.
  View toggleGap=sheet.body.getChildAt(sheet.body.indexOfChild(toggle)+1);sheet.body.removeView(toggleGap);sheet.body.removeView(toggle);sheet.body.addView(toggle,2);sheet.body.addView(toggleGap,3);
  sheet.action("Espandi tutti","expand",0,()->{model.all(false);refresh(true);});sheet.action("Riduci tutti","collapse",0,()->{model.all(true);refresh(true);});sheet.action("Modifica parametri del ciclo","edit",0,()->{if(selected!=null){Navigation n=new Navigation();n.checkId=selected.check;n.parameters=true;sheet.dismiss();navigate.accept(n);}});parameters=(Ui.Button)sheet.body.getChildAt(sheet.body.getChildCount()-2);
  sheet.primary("Apri sul foglio","edit",()->{if(nodeId!=null){Navigation n=new Navigation();n.nodeId=nodeId;sheet.dismiss();navigate.accept(n);}});open=(Ui.Button)sheet.footer.getChildAt(sheet.footer.getChildCount()-1);open.setTag("cycle-open");
  preview.setListener(new FlowCanvasView.Listener(){public void onBeforeChange(){throw new IllegalStateException("La panoramica è in sola lettura");}public void onDiagramChanged(String label){throw new IllegalStateException("La panoramica è in sola lettura");}public void onSelectionChanged(){}public void onEditRequested(String id){tap(id);}public boolean onReadOnlyNodeTap(String id){tap(id);return true;}public void onAddRequested(float x,float y,String from,String branch){throw new IllegalStateException("La panoramica è in sola lettura");}public void onConnectRequested(String id){throw new IllegalStateException("La panoramica è in sola lettura");}public void onConnectionStateChanged(String id,String branch){}public void onHint(String text){status.setText(text);}});
  refresh(false);preview.post(()->preview.fitToContent());
 }
 private void state(){toggle.setEnabled(selected!=null);parameters.setEnabled(selected!=null);open.setEnabled(nodeId!=null);choose.setEnabled(!model.cycles.isEmpty());choose.setText(selected==null?"Scegli ciclo ▾":shortHeader(selected)+" ▾");choose.setContentDescription(selected==null?"Scegli ciclo":"Ciclo selezionato: "+selected.header);toggle.setText(selected!=null&&model.isFolded(selected.check)?"Espandi ciclo":"Riduci ciclo");status.setText(selected==null?(model.cycles.isEmpty()?"Nessun ciclo con ingresso e uscita univoci. Il diagramma resta visibile.":"Scegli un ciclo o un blocco da aprire sul foglio."):selected.header+"\n"+selected.members.size()+" blocchi");}
 private String shortHeader(FlowCycle.Info c){return c.header.length()>100?c.header.substring(0,97)+"…":c.header;}
 private void tap(String id){FlowCycle.Info card=projection.cards.get(id);if(card!=null){selected=card;nodeId=card.entry;model.set(card.check,false);refresh(true);return;}nodeId=id;selected=null;for(FlowCycle.Info c:model.cycles)if(c.members.contains(id)&&(selected==null||c.members.size()<selected.members.size()))selected=c;preview.setHighlight(id);state();}
 void refresh(boolean animate){FlowCycleView.Projection previous=projection;projection=model.build();if(animate)Ui.crossfade(host,preview);preview.replaceNavigationGraph(projection,previous,animate);state();}
 private void chooseCycle(){child=new Ui.Sheet(owner,"Scegli ciclo","Seleziona anche un ciclo annidato, poi espandilo o aprilo sul foglio.");for(FlowCycle.Info c:model.cycles)child.choice(shortHeader(c),c.members.size()+" blocchi · "+(model.isFolded(c.check)?"Ridotto":"Espanso"),Ui.accentInk(),()->{selected=c;nodeId=c.entry;child.dismiss();state();});child.show();}
 void close(){if(child!=null)child.dismiss();preview.setListener(null);}
}
